function totalStat(key){let v=player[key]||0;for(const it of Object.values(player.gear))if(it&&it.stats[key])v+=it.stats[key];return v}
function showToast(s){const t=$('toast');t.textContent=s;t.classList.add('show');toastTimer=2.2}
function addParticle(x,y,color,n=8){for(let i=0;i<n;i++)particles.push({x,y,vx:rand(-90,90),vy:rand(-110,45),life:rand(.3,.75),max:.75,color,size:rand(2,5)})}
function spawnEnemy(){let a=rand(0,Math.PI*2),dist=Math.max(W,H)*.65+rand(20,180),x=clamp(player.x+Math.cos(a)*dist,30,world.w-30),y=clamp(player.y+Math.sin(a)*dist,30,world.h-30),t=elapsed;let type=t>100&&Math.random()<.22?'wraith':t>40&&Math.random()<.27?'brute':'ghoul';let e={id:++enemyId,x,y,type,r:type==='brute'?18:type==='wraith'?12:14,hp:0,maxhp:0,speed:type==='brute'?42:type==='wraith'?82:58,damage:type==='brute'?17:10,hit:0,attack:0,phase:rand(0,7),boss:false};e.maxhp=e.hp=(type==='brute'?52:type==='wraith'?22:28)*(1+elapsed/210);enemies.push(e)}
function spawnBoss(){let a=rand(0,6.28),e={id:++enemyId,x:clamp(player.x+Math.cos(a)*420,80,world.w-80),y:clamp(player.y+Math.sin(a)*420,80,world.h-80),type:'boss',r:29,hp:1250,maxhp:1250,speed:38,damage:24,hit:0,attack:0,phase:0,boss:true};enemies.push(e);$('bossbar').style.display='block';showToast('THE WARDEN OF ASH HAS FOUND YOU')}
function nearest(){let best=null,bd=Infinity;for(let e of enemies){let d=(e.x-player.x)**2+(e.y-player.y)**2;if(d<bd){bd=d;best=e}}return best}
function shoot(){let target=nearest();if(!target)return;let dx=target.x-player.x,dy=target.y-player.y,d=Math.hypot(dx,dy)||1;let crit=Math.random()<totalStat('crit');projectiles.push({x:player.x,y:player.y,vx:dx/d*410,vy:dy/d*410,life:1.15,r:5,damage:totalStat('damage')*(crit?2:1),crit,hit:new Set()});player.facing=dx<0?-1:1;attackTimer=1/Math.max(.4,player.rate+totalStat('speed'))}
function death(e){kills++;souls+=e.boss?150:e.type==='brute'?5:1;addParticle(e.x,e.y,e.boss?'#e44c52':e.type==='wraith'?'#99cbdd':'#a34e49',e.boss?30:10);let n=e.boss?16:e.type==='brute'?2:1;for(let i=0;i<n;i++)gems.push({x:e.x+rand(-12,12),y:e.y+rand(-12,12),value:e.boss?8:e.type==='brute'?2:1,r:e.boss?6:4,mag:0});if(Math.random()<(e.boss?.8:e.type==='brute'?.25:.095)){loot.push({x:e.x,y:e.y,item:makeItem(pick(slots)),phase:rand(0,7)})}if(e.boss){$('bossbar').style.display='none';showToast('WARDEN SLAIN · THE CRYPT REMEMBERS');for(let i=0;i<3;i++)loot.push({x:e.x+rand(-40,40),y:e.y+rand(-40,40),item:makeItem(pick(slots)),phase:rand(0,7)})}}
function levelUp(){level++;xp-=xpNeed;xpNeed=Math.ceil(xpNeed*1.35+2);paused=true;const options=[{ico:'⚔',name:'Keen Edge',desc:'+22% weapon damage. Let every strike count.',apply:()=>player.damage*=1.22},{ico:'✦',name:'Quick Hands',desc:'+18% attack speed. A storm of steel.',apply:()=>player.rate+=.18},{ico:'♥',name:'Blood Pact',desc:'+25 max health and restore 30 vitality.',apply:()=>{player.maxhp+=25;player.hp=Math.min(player.maxhp,player.hp+30)}},{ico:'⌁',name:'Fleetfoot',desc:'+14% movement speed. Never cornered.',apply:()=>player.move*=1.14},{ico:'◇',name:'Grave Magnet',desc:'+32 pickup radius. Leave nothing behind.',apply:()=>player.pickup+=32},{ico:'☠',name:'Black Omen',desc:'+4% critical chance and +8% damage.',apply:()=>{player.crit+=.04;player.damage*=1.08}}];let shuffled=options.sort(()=>Math.random()-.5).slice(0,3);$('choices').innerHTML='';for(const o of shuffled){let b=document.createElement('button');b.className='choice';b.innerHTML=`<span class="tag">BOON</span><div class="ico">${o.ico}</div><h3>${o.name}</h3><p>${o.desc}</p>`;b.onclick=()=>{o.apply();$('levelup').style.display='none';paused=false;syncHud()};$('choices').append(b)}$('newlevel').textContent=level;$('levelup').style.display='flex';syncHud()}
function pickupItem(i){let item=loot[i].item;loot.splice(i,1);itemsFound++;if(player.bag.length<12){player.bag.push(item);showToast(`${item.name} · ${item.rarity.toUpperCase()} RELIC — I TO INSPECT`)}else{showToast('BAG FULL · LEAVE ROOM FOR RELICS')}addParticle(player.x,player.y,rarity[item.rarity].color,10)}
function update(dt){if(!running||paused||gameOver)return;elapsed+=dt;if(elapsed>=480){winGame();return}if(elapsed>100&&elapsed<101&&!enemies.some(e=>e.boss))spawnBoss();let sx=move.x+(keys.KeyA||keys.ArrowLeft?-1:0)+(keys.KeyD||keys.ArrowRight?1:0),sy=move.y+(keys.KeyW||keys.ArrowUp?-1:0)+(keys.KeyS||keys.ArrowDown?1:0),len=Math.hypot(sx,sy);if(len>1){sx/=len;sy/=len}let mv=player.move+totalStat('move');player.x=clamp(player.x+sx*mv*dt,18,world.w-18);player.y=clamp(player.y+sy*mv*dt,18,world.h-18);player.invuln=Math.max(0,player.invuln-dt);attackTimer-=dt;if(attackTimer<=0)shoot();spawnTimer-=dt;if(spawnTimer<=0){spawnEnemy();if(elapsed>35&&Math.random()<.24)spawnEnemy();spawnTimer=Math.max(.24,.92-elapsed/800)+rand(0,.35)}
for(let i=enemies.length-1;i>=0;i--){let e=enemies[i],dx=player.x-e.x,dy=player.y-e.y,d=Math.hypot(dx,dy)||1;e.phase+=dt;e.hit=Math.max(0,e.hit-dt);if(d>e.r+player.r+1){e.x+=dx/d*e.speed*dt;e.y+=dy/d*e.speed*dt}else if(player.invuln<=0){player.hp-=e.damage;player.invuln=.55;addParticle(player.x,player.y,'#e2534c',5);if(player.hp<=0){player.hp=0;loseGame();break}}if(e.boss){$('bossfill').style.width=`${e.hp/e.maxhp*100}%`}}}
for(let p of projectiles){p.x+=p.vx*dt;p.y+=p.vy*dt;p.life-=dt;for(let e of enemies){if(p.hit.has(e.id))continue;if(Math.hypot(e.x-p.x,e.y-p.y)<e.r+p.r){p.hit.add(e.id);e.hp-=p.damage;e.hit=.12;addParticle(p.x,p.y,p.crit?'#f6d066':'#f3d9a1',p.crit?8:4);p.life=0;if(e.hp<=0){death(e);enemies.splice(enemies.indexOf(e),1)}break}}}projectiles=projectiles.filter(p=>p.life>0);
for(let g of gems){let d=Math.hypot(g.x-player.x,g.y-player.y),range=totalStat('pickup');if(d<range){let force=1+(range-d)/range*6;g.x+=(player.x-g.x)/Math.max(d,1)*190*force*dt;g.y+=(player.y-g.y)/Math.max(d,1)*190*force*dt;if(d<player.r+g.r+4){xp+=g.value;souls+=g.value;addParticle(player.x,player.y,'#b98bdf',4);g.got=true;if(xp>=xpNeed)levelUp()}}g.mag+=dt*3}gems=gems.filter(g=>!g.got);
for(let i=loot.length-1;i>=0;i--){let l=loot[i];l.phase+=dt;let d=Math.hypot(l.x-player.x,l.y-player.y);if(d<28){pickupItem(i);continue}if(d<totalStat('pickup')*.72){l.x+=(player.x-l.x)/d*35*dt;l.y+=(player.y-l.y)/d*35*dt}}
for(let p of particles){p.x+=p.vx*dt;p.y+=p.vy*dt;p.vy+=130*dt;p.life-=dt}particles=particles.filter(p=>p.life>0);if(toastTimer>0){toastTimer-=dt;if(toastTimer<=0)$('toast').classList.remove('show')}syncHud()}

