function rr(x,y,w,h,r){ctx.beginPath();ctx.roundRect(x,y,w,h,r)}
function draw(){ctx.clearRect(0,0,W,H);const camx=clamp(player.x-W/2,0,world.w-W),camy=clamp(player.y-H/2,0,world.h-H);ctx.save();ctx.translate(-camx,-camy);ctx.fillStyle='#24251f';ctx.fillRect(camx,camy,W,H);ctx.strokeStyle='#323129';ctx.lineWidth=1;let grid=96;for(let x=Math.floor(camx/grid)*grid;x<camx+W+grid;x+=grid){for(let y=Math.floor(camy/grid)*grid;y<camy+H+grid;y+=grid){let seed=Math.sin(x*12.9898+y*78.233)*43758.5453;seed-=Math.floor(seed);ctx.fillStyle=seed>.5?'#292a23':'#262720';ctx.fillRect(x,y,grid-1,grid-1);if(seed>.76){ctx.fillStyle='#33342b';ctx.beginPath();ctx.ellipse(x+seed*80,y+(seed*83)%90,12,4,.5,0,6.28);ctx.fill()}ctx.strokeStyle='#303129';ctx.strokeRect(x,y,grid,grid)}}
