function syncHud(){if(!player)return;$('time').textContent=fmt(elapsed);$('level').textContent=String(level).padStart(2,'0');$('souls').textContent=souls.toLocaleString();$('hptext').textContent=`${Math.ceil(player.hp)} / ${Math.ceil(player.maxhp)}`;$('hpfill').style.width=`${clamp(player.hp/player.maxhp*100,0,100)}%`;$('xptext').textContent=`${Math.floor(xp)} / ${xpNeed}`;$('xpfill').style.width=`${clamp(xp/xpNeed*100,0,100)}%`;$('lootcount').textContent=`BAG ${player.bag.length}/12`;let gear=player.gear.Weapon;$('weaponname').textContent=gear?gear.name.toUpperCase():'ASHEN DAGGER';}
let inventoryFromPause=false;
function statsText(it){return Object.entries(it.stats).map(([k,v])=>`${v>0?'+':''}${v}${k==='crit'||k==='speed'||k==='move'?'':' '} ${statPool.find(s=>s[0]===k)?.[1]||k}`).join(' · ')}
function openBag(fromPause=false){if(!running||gameOver)return;inventoryFromPause=fromPause;paused=true;if(fromPause)$('pause').style.display='none';renderBag();$('inventory').style.display='flex'}
function closeBag(){ $('inventory').style.display='none';if(inventoryFromPause){$('pause').style.display='flex';paused=true}else if($('levelup').style.display!=='flex')paused=false;}
function renderBag(){let eg=$('equipped'),bag=$('bag');eg.innerHTML='';for(let slot of slots){let it=player.gear[slot],div=document.createElement('div');div.className='slot';div.innerHTML=`<div class="slotname">${slot.toUpperCase()}</div><div class="itemname ${it?'rarity-'+it.rarity:''}">${it?`${it.glyph} ${it.name}`:'— Empty —'}</div>`;if(it)div.title=statsText(it);eg.append(div)}bag.innerHTML='';$('baglabel').textContent=`(${player.bag.length}/12)`;if(!player.bag.length){bag.innerHTML='<div class="emptybag">No relics yet. The crypt is generous to those who survive.</div>';return}player.bag.forEach((it,i)=>{let b=document.createElement('button');b.className='itemrow';b.innerHTML=`<span class="itemglyph ${'rarity-'+it.rarity}">${it.glyph}</span><span class="iteminfo"><b class="${'rarity-'+it.rarity}">${it.name}</b><span>${it.rarity.toUpperCase()} · ${it.slot.toUpperCase()}<br>${statsText(it)}</span></span><span class="equiplabel">EQUIP ›</span>`;b.onclick=()=>equip(i);bag.append(b)})}
function equip(i){let it=player.bag.splice(i,1)[0],old=player.gear[it.slot];player.gear[it.slot]=it;if(old)player.bag.push(old);for(const [k,v] of Object.entries(it.stats)){if(k==='maxhp'){player.maxhp+=v;player.hp=Math.min(player.maxhp,player.hp+Math.max(1,v*.35))}}if(old&&old.stats.maxhp){player.maxhp-=old.stats.maxhp;player.hp=Math.min(player.hp,player.maxhp)}showToast(`${it.name.toUpperCase()} EQUIPPED`);renderBag();syncHud()}
function togglePause(){if(!running||gameOver||$('levelup').style.display==='flex'||$('inventory').style.display==='flex')return;paused=!paused;$('pause').style.display=paused?'flex':'none'}
function loseGame(){gameOver=true;paused=true;$('endeyebrow').textContent='Your tale is told';$('endtitle').textContent='Fallen, not forgotten.';$('endcopy').textContent='The crypt claims another soul. But the relics you found may yet tell a different tale.';endStats()}
function winGame(){gameOver=true;paused=true;$('endeyebrow').textContent='The dawn breaks';$('endtitle').textContent='The crypt is silent.';$('endcopy').textContent='You endured the night and broke the Warden’s curse. The first light is yours.';endStats()}
function endStats(){$('endtime').textContent=fmt(elapsed);$('endlevel').textContent=level;$('endkills').textContent=kills;$('endrelics').textContent=itemsFound;$('end').style.display='flex'}
